package com.voicetxt.reader;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.*;
public class ReadingLanguageStyleTest extends Instrumentation {
    void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
    void ui(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    void await(java.util.function.BooleanSupplier condition,String label)throws Exception{long end=SystemClock.elapsedRealtime()+35000;while(SystemClock.elapsedRealtime()<end){AtomicBoolean ready=new AtomicBoolean();ui(()->ready.set(condition.getAsBoolean()));if(ready.get())return;Thread.sleep(50);}throw new AssertionError(label);}
    void screenshot(String name)throws Exception{waitForIdleSync();Thread.sleep(500);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}
    public void onCreate(Bundle b){super.onCreate(b);start();}
    public void onStart(){Bundle result=new Bundle();MainActivity activity=null;boolean passed=false;Context context=getTargetContext();String locale=context.getSystemService(LocaleManager.class).getApplicationLocales().toLanguageTags();android.content.SharedPreferences prefs=context.getSharedPreferences("reading_settings",0);Map<String,?> backup=prefs.getAll();String[] changed={"readingLanguage","systemVoiceKey","chineseVoiceKey","englishVoiceKey"};try{
        try(FileOutputStream out=new FileOutputStream(new File(context.getFilesDir(),"book_reading_language_style_qa.txt"))){StringBuilder source=new StringBuilder("第一章 山间的风\n");for(int i=0;i<30;i++)source.append("风吹过山间，书页轻轻翻动。让每一段文字都有声音。\n");out.write(source.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}
        activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","reading_language_style_qa").putExtra("book_name","阅读语言 · 界面验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity a=activity;await(()->a.offlineReady&&a.system.initialized,"voices not ready");ui(()->{StringBuilder text=new StringBuilder("第一章 山间的风\n");for(int i=0;i<30;i++)text.append("风吹过山间，书页轻轻翻动。让每一段文字都有声音。\n");a.text=text.toString();a.chapters=MainActivity.parse(a.text);a.position=0;a.readingLanguage="";a.systemVoiceKey=a.system.offlineVoice("zh","").key;a.night=false;a.theme();a.showPosition(true);a.chooseReadingLanguage();});await(()->a.languagePicker!=null&&a.languagePicker.isShowing(),"sheet not shown");ui(()->{check(a.languagePicker.choices.size()==4,"missing language cards");check(a.languagePicker.choices.get("").isSelected(),"original text not selected");});screenshot("reading-language-day.png");
        ui(()->{a.languagePicker.dismiss();a.translation.ready=true;a.chooseReadingLanguage();a.languagePicker.choices.get("zh").performClick();check(a.readingLanguage.equals("zh")&&(a.languagePicker==null||!a.languagePicker.isShowing()),"Chinese selection failed");a.chooseReadingLanguage();check(a.languagePicker.choices.get("zh").isSelected()&&!a.languagePicker.choices.get("").isSelected(),"selected state not exclusive");});screenshot("reading-language-chinese.png");ui(()->{a.languagePicker.choices.get("en").performClick();check(a.readingLanguage.equals("en")&&a.system.find(a.systemVoiceKey).voice.getLocale().getLanguage().equals("en"),"English selection/voice failed");a.night=true;a.theme();a.chooseReadingLanguage();});screenshot("reading-language-night.png");
        ui(()->{a.languagePicker.dismiss();a.night=false;a.theme();a.readingLanguage="";a.systemVoiceKey=a.system.offlineVoice("zh","").key;a.startReading();});await(()->a.playing&&a.focusGeneration==a.generation,"reading did not start");int generation=a.generation;ui(()->{a.chooseReadingLanguage();a.languagePicker.choices.get("").performClick();check(a.playing&&a.generation==generation,"selecting current language interrupted reading");a.chooseReadingLanguage();a.languagePicker.dismiss();check(a.playing&&a.generation==generation,"dismissing sheet interrupted reading");a.stop();});
        ui(()->a.finish());activity=null;
        ui(()->context.getSystemService(LocaleManager.class).setApplicationLocales(LocaleList.forLanguageTags("en")));Thread.sleep(500);activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","reading_language_style_qa").putExtra("book_name","阅读语言 · 界面验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity english=activity;await(()->!english.text.isEmpty()&&!english.chapters.isEmpty(),"English book restore failed");ui(()->{english.translation.ready=false;english.chooseReadingLanguage();});screenshot("reading-language-en.png");ui(()->{english.languagePicker.dismiss();english.finish();});activity=null;
        ui(()->context.getSystemService(LocaleManager.class).setApplicationLocales(LocaleList.forLanguageTags("ar")));Thread.sleep(500);activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).putExtra("book_id","reading_language_style_qa").putExtra("book_name","阅读语言 · 界面验证").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity arabic=activity;await(()->!arabic.text.isEmpty()&&!arabic.chapters.isEmpty(),"Arabic book restore failed");ui(()->{arabic.chooseReadingLanguage();check(!arabic.destroyed,"Arabic reader destroyed");});await(()->arabic.languagePicker.panel.getLayoutDirection()==View.LAYOUT_DIRECTION_RTL,"RTL layout not applied");screenshot("reading-language-ar.png");result.putString("result","PASS: four language cards; exclusive selection; Chinese/English target and offline English voice; current selection/dismiss keeps playback; day/night; English and Arabic RTL; no model download triggered");passed=true;
    }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(activity!=null){final MainActivity a=activity;ui(()->{a.stop();a.finish();});}ui(()->context.getSystemService(LocaleManager.class).setApplicationLocales(LocaleList.forLanguageTags(locale)));android.content.SharedPreferences.Editor restore=prefs.edit();for(String key:changed){restore.remove(key);if(backup.containsKey(key))restore.putString(key,(String)backup.get(key));}restore.commit();waitForIdleSync();new File(context.getFilesDir(),"book_reading_language_style_qa.txt").delete();context.getSharedPreferences("reader_reading_language_style_qa",0).edit().clear().commit();new File(context.getFilesDir(),"book_reading_language_style_qa.txt.position").delete();}finish(passed?-1:0,result);}
}


